// Deterministic CPU triangle depth buffer shared by solid shoes and deforming printed paper.
export function rasterSurface(width,height,triangles,texture=null){const pixels=new Uint8ClampedArray(width*height*4),depth=new Float32Array(width*height);depth.fill(-Infinity);for(const face of triangles){const [a,b,c]=face.points,den=(b[1]-c[1])*(a[0]-c[0])+(c[0]-b[0])*(a[1]-c[1]);if(Math.abs(den)<1e-8)continue;const minX=Math.max(0,Math.floor(Math.min(a[0],b[0],c[0]))),maxX=Math.min(width-1,Math.ceil(Math.max(a[0],b[0],c[0]))),minY=Math.max(0,Math.floor(Math.min(a[1],b[1],c[1]))),maxY=Math.min(height-1,Math.ceil(Math.max(a[1],b[1],c[1])));for(let y=minY;y<=maxY;y++)for(let x=minX;x<=maxX;x++){const X=x+.5,Y=y+.5,A=((b[1]-c[1])*(X-c[0])+(c[0]-b[0])*(Y-c[1]))/den,B=((c[1]-a[1])*(X-c[0])+(a[0]-c[0])*(Y-c[1]))/den,C=1-A-B;if(A< -1e-7||B< -1e-7||C< -1e-7)continue;const inv=a.length>5?A*a[5]+B*b[5]+C*c[5]:0,z=inv?-1/inv:A*a[2]+B*b[2]+C*c[2],i=y*width+x;if(z<depth[i])continue;const p=i*4;let color=face.color||[180,174,160],alpha=255;const tex=face.texture||texture;if(tex&&!face.untextured){let U=inv?(A*a[3]*a[5]+B*b[3]*b[5]+C*c[3]*c[5])/inv:A*a[3]+B*b[3]+C*c[3],V=inv?(A*a[4]*a[5]+B*b[4]*b[5]+C*c[4]*c[5])/inv:A*a[4]+B*b[4]+C*c[4];if(face.repeat){U=((U%1)+1)%1;V=((V%1)+1)%1;}const u=Math.max(0,Math.min(tex.width-1,U*(tex.width-1))),v=Math.max(0,Math.min(tex.height-1,V*(tex.height-1)));if(face.smoothTexture){const X=Math.floor(u),Y=Math.floor(v),dx=u-X,dy=v-Y,ids=[(Y*tex.width+X)*4,(Y*tex.width+Math.min(X+1,tex.width-1))*4,(Math.min(Y+1,tex.height-1)*tex.width+X)*4,(Math.min(Y+1,tex.height-1)*tex.width+Math.min(X+1,tex.width-1))*4],weights=[(1-dx)*(1-dy),dx*(1-dy),(1-dx)*dy,dx*dy],sample=k=>ids.reduce((s,id,i)=>s+tex.data[id+k]*weights[i],0);color=[sample(0),sample(1),sample(2)];alpha=sample(3);}else{const j=(Math.round(v)*tex.width+Math.round(u))*4;color=tex.data.subarray(j,j+3);alpha=tex.data[j+3];}if(!alpha)continue;}if(face.alphaCutoff){if(alpha<face.alphaCutoff)continue;alpha=255;}depth[i]=z;let shade=face.shade??1;if(face.grain){const u=A*a[3]+B*b[3]+C*c[3],v=A*a[4]+B*b[4]+C*c[4],raw=Math.sin(u*2389.3+v*7183.1)*43758.5453,n=raw-Math.floor(raw),crease=Math.abs(Math.sin(u*113+Math.sin(v*27)*2));shade*=1+face.grain*((n-.5)*.8+(crease-.5)*.65);}for(let k=0;k<3;k++)pixels[p+k]=Math.min(255,color[k]*shade);pixels[p+3]=alpha;}}return {pixels,depth};}
export function putSurface(canvas,result){const c=canvas.getContext('2d'),im=c.createImageData(canvas.width,canvas.height);im.data.set(result.pixels);c.putImageData(im,0,0);return canvas;}
